def normal_valid(n:C.Vec3) -> Bool:
  C.Vec3{+x,+y,+z} = n
  +size = (x * x + y * y + z * z : F32)
  vec_finite(C.Vec3{x,y,z}) && finite(size) && F32.is_gt(size,0.000000000001) && F32.is_le(size,1000000000000.0)

